WITH base AS (SELECT id, channel, promo_code, starts_on, ends_on, UPPER(promo_code) AS promo_code_upper, COALESCE(channel, 'NONE') AS channel_filled FROM promotions WHERE ends_on >= DATE '2023-08-25'), attributed AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct FROM base a INNER JOIN promotions pr ON a.channel <=> pr.channel AND a.ends_on >= pr.starts_on AND a.ends_on < pr.ends_on + INTERVAL '30' DAY), filtered AS (SELECT id, channel, promo_code, starts_on, ends_on, promo_id, promotion_promo_code, discount_pct - promo_id AS discount_pct_minus_promo_id FROM attributed WHERE ends_on > DATE '2023-09-21' AND promotion_promo_code IS NOT NULL), attributed_promotions AS (SELECT e.*, pr.id AS promo_id_2, pr.promo_code AS promotion_promo_code_2, pr.discount_pct FROM filtered e LEFT JOIN promotions pr ON e.channel = pr.channel AND e.ends_on >= pr.starts_on AND e.ends_on < pr.ends_on + INTERVAL '7' DAY), cleaned AS (SELECT id, channel, promo_code, starts_on, promo_id, promotion_promo_code, discount_pct_minus_promo_id, promo_id_2, discount_pct, ROUND(discount_pct, 1) AS discount_pct_rounded, CAST(promo_id AS DOUBLE) AS promo_id_num FROM attributed_promotions WHERE ends_on > TO_DATE('2023-08-08')) SELECT CASE WHEN promo_id >= 9 THEN 'HIGH' ELSE 'LOW' END AS promo_id_tier, promotion_promo_code, PERCENTILE_APPROX(promo_id_2, 0.5) AS promo_id_2_p50, COUNT(CASE WHEN channel = 'mobile' THEN 1 END) AS mobile_count, ROUND(SUM(discount_pct_minus_promo_id) / NULLIF(COUNT(CASE WHEN promo_code = 'SPRING10' THEN 1 END), 0), 2) AS discount_pct_minus_promo_id_per_spring10, AVG(promo_id) AS avg_promo_id, ROUND(AVG(promo_id_2), 2) AS avg_promo_id_2, DENSE_RANK() OVER (PARTITION BY CASE WHEN promo_id >= 9 THEN 'HIGH' ELSE 'LOW' END ORDER BY ROUND(AVG(promo_id_2), 2) DESC) AS avg_promo_id_2_dense_rank FROM cleaned GROUP BY CASE WHEN promo_id >= 9 THEN 'HIGH' ELSE 'LOW' END, promotion_promo_code ORDER BY avg_promo_id_2 DESC NULLS FIRST
